CREATE POLICY "documents_passport_refresh" ON "documents" AS PERMISSIVE FOR SELECT TO "homecrm_owner" USING (pg_trigger_depth()>0 AND data->>'type'='russian_passport' AND (owner_account_id=nullif(current_setting('app.passport_owner_account',true),'')::uuid OR owner_contact_id=nullif(current_setting('app.passport_owner_contact',true),'')::uuid));--> statement-breakpoint
CREATE POLICY "spaces_passport_timezone" ON "spaces" AS PERMISSIVE FOR SELECT TO "homecrm_owner" USING (pg_trigger_depth()>0 AND id=nullif(current_setting('app.passport_house_id',true),'')::uuid AND kind='household');